package app.kinnect.live;
import android.app.*;
import android.content.Intent;
import android.net.Uri;
import org.json.*;
import java.net.*;
/** Checks published APK releases and downloads and verifies an update inside Kinnect. */
public final class ApkUpdates {
 public static void check(Activity activity){ProgressDialog progress=ProgressDialog.show(activity,I18n.t("Cập nhật Kinnect"),I18n.t("Đang kiểm tra phiên bản…"),true,false);new Thread(()->{String version=null,url=null,digest=null,error=null;long size=0;try{String current=activity.getPackageManager().getPackageInfo(activity.getPackageName(),0).versionName;HttpURLConnection c=(HttpURLConnection)new URL("https://api.github.com/repos/vuanh97nd/Kinnect/releases?per_page=30").openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","Kinnect-Android/"+current);JSONArray releases;try{if(c.getResponseCode()!=200)throw new Exception();releases=new JSONArray(new String(NativeApi.read(c.getInputStream(),2000000),"UTF-8"));}finally{c.disconnect();}for(int i=0;i<releases.length();i++){JSONObject r=releases.getJSONObject(i);if(r.optBoolean("draft")||r.optBoolean("prerelease"))continue;String tag=r.optString("tag_name");try{if(ReleaseVersion.compare(tag,current)<=0||(version!=null&&ReleaseVersion.compare(tag,version)<=0))continue;}catch(IllegalArgumentException invalid){continue;}JSONArray assets=r.optJSONArray("assets");for(int j=0;assets!=null&&j<assets.length();j++){JSONObject asset=assets.getJSONObject(j);String link=asset.optString("browser_download_url");if(asset.optString("name").equals("Kinnect-"+tag.replaceFirst("^v","")+"-native.apk")&&ApkUpdatePolicy.validSize(asset.optLong("size"))&&ApkUpdatePolicy.releaseUrl(link)){String verified=ApkUpdatePolicy.digest(asset.optString("digest"));version=tag;url=link;digest=verified;size=asset.optLong("size");break;}}}}catch(Exception e){error=I18n.t("Chưa kiểm tra được cập nhật. Vui lòng thử lại khi có mạng.");}final String v=version,u=url,h=digest,e=error;final long bytes=size;activity.runOnUiThread(()->{if(activity.isFinishing()||activity.isDestroyed())return;progress.dismiss();if(e!=null){new Sheet(activity).setMessage(e).setPositiveButton(I18n.t("Đóng"),null).show();return;}if(u==null){new Sheet(activity).setTitle(I18n.t("Kinnect đã mới nhất")).setMessage(I18n.t("Chưa có APK mới hơn phiên bản đang cài.")).setPositiveButton("Xong",null).show();return;}new Sheet(activity).setTitle(I18n.t("Có bản Kinnect ")+v).setMessage(I18n.t("App sẽ tải và xác minh APK ngay tại đây, sau đó mở trình cài đặt Android. Giữ nguyên dữ liệu tài khoản. Không chuyển sang Chrome.")).setPositiveButton(I18n.t("Đồng ý cập nhật"),(d,w)->ApkUpdateActivity.open(activity,v,u,h,bytes)).setNegativeButton(I18n.t("Để sau"),null).show();});},"kinnect-updates").start();}
}
